class C {
    public required string Name { get; init; }
    public readonly string Code;
    public C() : this(true) { Print(Name); Print(Code); Name += "-outer"; }
    public C(bool choose) { Code = "code"; if (choose) { Name = "left"; return; } Name = "right"; }
}
void Main() { var c = new C { Name = "caller" }; Print(c.Name); }
